INSERT INTO content_items (collection, path, slug, title, status, body, metadata_json, cover_image, published_at) VALUES ('articles', '_articles/guides/cfhibiscus.md', 'cfhibiscus', 'Plants with hibiscus-like flowers compared ', 'published', '[![](../../../Templates/wildfactsheet3.gif)](../../indexl)

