INSERT INTO content_items (collection, path, slug, title, status, body, metadata_json, cover_image, published_at) VALUES ('photoindexes', '_photoindexes/plants/seaweed/seaweedfi.md', 'seaweedfi', 'Photo index of seaweeds on Singapore shores', 'published', '{% for row in page.child_pages %}<div class="photo-index-images-text-row">
{% include img-grid.html items=row.images cols=4 %}
  <div>
    <p>{{ row.label | markdownify}}</p>
  
  </div>
</div>
{% endfor %}
<hr/>
These 
      are NOT seaweeds, they are seagrasses <br/>
see the <a href="../seagrass/seagrassfi.htm">seagrass 
      photo index</a><br/>
<table cellpadding="6" width="100%">
<tr>
<td valign="top" width="20%">
<div align="center"><img height="108" src="../seagrass/ovalis/040523sjiad0057m.jpg" width="108"/><a href="../seagrass/ovalis.htm"><br/>
              Spoon seagrass </a><i><br/>
              Halophila ovalis </i>complex </div>
</td>
<td valign="top" width="20%">
<div align="center"><img height="108" src="../seagrass/halodule/050611kusd4016m.jpg" width="108"/><a href="../seagrass/halodule.htm"><br/>
              Needle seagrass</a> <i><br/>
              Halodule pinifolia<br/>
</i>and<i> H. univervis</i></div>
</td>
<td valign="top" width="20%">
<div align="center"><img height="108" src="../seagrass/enhalus/040620skdd0750m.jpg" width="108"/><a href="../seagrass/enhalus.htm"><br/>
              Tape seagrass</a><i></i></div>
</td>
<td valign="top" width="20%">
<div align="center"><img height="108" src="../seagrass/thalassia/041019labd7736m.jpg" width="108"/><a href="../seagrass/thalassia.htm"><br/>
              Sickle seagrass</a> <i><br/>
