INSERT INTO content_items (collection, path, slug, title, status, body, metadata_json, cover_image, published_at) VALUES ('photoindexes', '_photoindexes/vertebrates.html', 'vertebrates', 'Photo index', 'published', '
{% include global/header.html %}

<style>
    .photoindex-cards{
        display:flex;
        gap:0.5rem;
        margin-bottom: 1rem;
    }
    .photoindex-card .text{
        padding:0.5rem;
    }
    .photoindex-card{
        border:1px solid rgb(218, 218, 218);
        overflow: hidden;
        border-radius: 8px;
        width: 150px;
    }
    .photoindex-card img{
        width:100%;
        aspect-ratio: 1;
        object-fit: cover;
        object-position: center;
    }
</style>

<main class="page-content" id="main-content">
{% for section in page.sections %}
<h3>{{section.label}}</h3>
<div class="photoindex-cards">
    {% for card in section.children %}
    <a href="{{card.link}}" class="photoindex-card">
        <img src="{{card.img}}" alt="">
        <div class="text">
            <p>{{card.text}}</p>
        </div>
    </a>
    {% endfor %}
</div>
{% endfor %}
</main>

